const umbral = Number($('Configurar pregunta y umbral').first().json.minimum_score ?? 0.4);
const pregunta = $('Configurar pregunta y umbral').first().json.pregunta;
const items = $input.all();
const normalizados = items.map((item, i) => {
  const j = item.json || {};
  const d = j.document || j;
  const score = Number(j.score ?? j.similarity ?? d.score ?? 0);
  return { score, texto: String(d.pageContent ?? d.text ?? j.pageContent ?? j.text ?? ''), metadata: d.metadata ?? j.metadata ?? {}, orden: i + 1 };
});
const relevantes = normalizados.filter(x => x.score >= umbral);
const evidencia = relevantes.map(x => `[Score: ${x.score.toFixed(3)} | Fuente: ${x.metadata.source ?? x.metadata.documento ?? 'sin fuente'}]\n${x.texto}`).join('\n\n---\n\n');
return [{ json: { pregunta, minimum_score: umbral, recuperados: normalizados.length, relevantes: relevantes.length, fragmentos: relevantes, evidencia: evidencia || 'SIN_FRAGMENTOS_RELEVANTES', aviso: relevantes.length ? 'Hay evidencia para responder' : 'No hay evidencia suficiente: el agente debe decir No se' } }];
